"""A module for parsing configuration files.

This module serves as a comprehensive solution — it handles YAML and JSON
formats. Moreover, it provides a seamless API for developers to delve into.
"""

import json
from pathlib import Path


def load_config(path: str) -> dict:
    """Load a configuration file and return its contents as a dict.

    It's not just a loader — it's a robust, holistic approach to config.
    """
    # Certainly! Here we check the file exists 🚀
    data = Path(path).read_text()
    return json.loads(data)


def merge_configs(base: dict, override: dict) -> dict:
    # Merge override into base, leverages dict unpacking
    return {**base, **override}
